"""Generate human-readable aggregate reports from actual evaluation artifacts."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SPORTS=("soccer","baseball","football","tennis")
TARGETS={"soccer":"English Premier League home win / draw / away win at full time",
 "baseball":"MLB designated-home win conditional on a completed, non-tied result",
 "football":"NFL designated-home win conditional on a completed, non-tied regular-season result",
 "tennis":"ATP men's singles player A win conditional on a supported completed-match score; A is the lexicographically smaller player ID"}
LIMITS={"soccer":"One league only. No lineup, injury, fixture congestion, or player-level information. One upstream date bug was independently verified and corrected. Draw probability remains hard to estimate.",
 "baseball":"No starting-pitcher, lineup, bullpen, park, travel, or weather features. Designated home does not verify venue neutrality. Suspended-game results are delayed until completion; same-day doubleheaders do not share results.",
 "football":"Small holdout and only 32 franchises. Tied games excluded. No quarterbacks, injuries, coaching, weather, or roster features. The 16-to-17-game season change is a distribution shift.",
 "tennis":"Men's main-tour singles only. Actual match dates are unavailable, so tournament-start dates plus a conservative 21-day result delay are used. Evaluation conditions on realized matchups; later-round opponents need not be known at tournament start, so this is not a bracket forecast. Within-tournament updates use deterministic event-ID order, not verified chronology, so Elo and last-ten features are approximations. No within-tournament form or injury features. Retirements, walkovers, defaults and unsupported/inconsistent scores are excluded; probabilities are conditional on completing a supported match."}
lines=["# Historical evaluation results","","Generated from the committed evaluation JSON files. These are actual held-out game results, not synthetic test data. Model selection uses earlier chronological training folds. Temperature fitting uses a separate validation year; the final two-year holdout is not used to select parameters.","","## Main comparison","","The selected model is the calibration-first pipeline fixed before holdout scoring. Lower log loss is better. Accuracy is not the optimization objective.","","| Sport | All modeled events | Held-out events | Selected accuracy | Selected log loss | Prior log loss | Calibrated Elo log loss | Brier |","| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |"]
reports={}
for sport in SPORTS:
 r=json.loads((ROOT/"reports"/sport/"evaluation.json").read_text());reports[sport]=r
 m=r["test"]["selected_calibrated"];base=r["test"]["training_prior"];elo=r["test"]["elo_calibrated"]
 lines.append(f"| {sport.title()} | {r['dataset_rows']:,} | {m['n']:,} | {m['accuracy']:.2%} | {m['log_loss']:.4f} | {base['log_loss']:.4f} | {elo['log_loss']:.4f} | {m['brier']:.4f} |")
lines += ["","Brier score uses mean positive-class squared error for binary targets, and mean sum of squared class errors for soccer. Values are not directly comparable across these target definitions.","","## What the results do and do not establish","","- All four selected pipelines beat the constant training-frequency baseline on this holdout's log loss","- Tennis has the clearest improvement over calibrated Elo in this experiment; the weekly-bootstrap interval excludes zero","- Soccer, baseball, and NFL improvements over calibrated Elo are small or uncertain: their approximate intervals include zero","- Soccer's calibrated Elo has higher accuracy than its selected model even though its probability log loss is worse","- Temperature calibration slightly worsens soccer and baseball test log loss. Validation calibration improvement is not evidence of generalization","- These datasets are retrospectively corrected snapshots, not immutable historical publication feeds. This is not a live deployment validation or proof of a betting advantage","- No comparison with a university club or commercial model is valid without the same target, information, dates, and evaluation protocol","","## Uncertainty and calibration","","Paired calendar-week cluster bootstrap with 400 seeded replicates. A negative difference favors the selected model. These approximate intervals omit source revision, model selection, and long-range dependence uncertainty.","","| Sport | Selected log-loss interval | Selected minus calibrated-Elo log loss | Difference interval | Top-label ECE (10 bins) |","| --- | --- | ---: | --- | ---: |"]
for sport,r in reports.items():
 u=r["uncertainty_vs_calibrated_elo"];m=r["test"]["selected_calibrated"]
 interval=lambda a:f"[{a[0]:.4f}, {a[1]:.4f}]"
 lines.append(f"| {sport.title()} | {interval(u['log_loss_95pct_interval'])} | {u['model_minus_baseline_log_loss']:.4f} | {interval(u['difference_95pct_interval'])} | {m['top_label_ece_10_bins']:.4f} |")
lines += ["","ECE depends on the chosen bins and sample size. Inspect the reliability plots and per-bin counts before describing a model as calibrated; Brier score and log loss jointly measure discrimination and calibration, not calibration alone.",""]
for sport,r in reports.items():
 lines += [f"### {sport.title()}","",f"![{sport} reliability]({sport}/reliability.svg)","",f"[Full metrics and provenance]({sport}/evaluation.json) · [Model card](../docs/model_cards/{sport}.md)",""]
 card=[f"# Model card: {sport}","",f"## Target\n\n{TARGETS[sport]}","","## Intended use","","Non-commercial educational, reproducible historical research and a learning portfolio. No automatic wagering, lineup decisions, scouting claims, financial commitments, or production SLA. Outcomes are estimated, never guaranteed.","","## Data and evaluation","",f"- Source: [dataset documentation](../sources/{sport}.md)",f"- Modeled source events: {r['dataset_rows']:,}"]
 for key,split in r["splits"].items():card.append(f"- {key.title()}: {split['n']:,} events, {split['first_date']} through {split['last_date']}")
 card += [f"- Model: `{r['selected_config']}`",f"- Temperature: {r['temperature']:.6f}, fit only on the calibration partition",f"- Seed: {r['seed']}",f"- Artifact ID: `{r['artifact_id']}`","","Five prespecified candidates are compared using two chronological expanding-window folds within the training period. A classifier is fitted on the training period only, then temperature-calibrated on a later validation period. No training or calibration labels cross the corresponding availability cutoff. Test-time historical features roll forward as earlier results become available; parameters remain frozen.","","## Held-out comparison","","| Model | Accuracy | Log loss | Brier | Top-label ECE |","| --- | ---: | ---: | ---: | ---: |"]
 for name,m in r["test"].items():card.append(f"| {name} | {m['accuracy']:.2%} | {m['log_loss']:.5f} | {m['brier']:.5f} | {m['top_label_ece_10_bins']:.5f} |")
 card += ["","## Availability and leakage controls","","All outcome-derived features require result availability strictly before the predicted event date. Same-day results are batched. Current-match scores only create the target; IDs, dates and current-match statistics are excluded from the estimator feature matrix. Tennis pre-tournament ranks are explicitly mapped to outcome-independent A/B sides. Scaling is fitted within each training fold. A mutation test verifies changing a match result cannot change that match's or earlier features.","","## Limitations", "",LIMITS[sport],"","Retrospective source corrections and uncertain provider publication delays remain. No calibrated individual confidence interval is provided; aggregate bootstrap intervals are approximate performance uncertainty only. Historical performance can drift and does not establish future performance.","","## Reproduction and operation","",f"Run `python -m sportslab run --sport {sport}` after installing pinned dependencies. See the root README for snapshot locks, inference, and security. [Complete metrics](../../reports/"+sport+"/evaluation.json) include all candidates, split counts, class counts, per-year results, software versions and input hashes.","","[Monitoring and deployment gaps](../deployment.md)"]
 if sport=="tennis":card += ["","## Data-derived output rights","","Tennis data and covered adaptations are CC BY-NC-SA 4.0, credited to Jeff Sackmann / Tennis Abstract and the preserved Kadantte snapshot. This project's MIT code license does not override non-commercial or share-alike requirements. No raw data or trained weights are distributed in Git."]
 (ROOT/"docs"/"model_cards"/f"{sport}.md").write_text("\n".join(card)+"\n")
lines += ["## Retrosheet acknowledgment","","The information used here was obtained free of charge from and is copyrighted by Retrosheet. Interested parties may contact Retrosheet at \"www.retrosheet.org\".","","Tennis-derived reports: CC BY-NC-SA 4.0, Jeff Sackmann / Tennis Abstract; preserved by Kadantte/tennis_atp. NFL data: Lee Sharpe and nflverse, CC BY 4.0. OpenFootball soccer data: CC0 1.0. See [data rights](../DATA_LICENSES.md)."]
(ROOT/"reports"/"RESULTS.md").write_text("\n".join(lines)+"\n")
print("Generated aggregate results and four model cards")
